import express, { type Express, Request, Response } from "express";
import cors from "cors";
import cookieParser from "cookie-parser";
import pinoHttp from "pino-http";
import router from "./routes/index.js";
import { logger } from "./lib/logger.js";

const app: Express = express();

app.use(
  pinoHttp({
    logger,
    serializers: {
      req(req: Request) {
        return { id: req.id, method: req.method, url: req.url?.split("?")[0] };
      },
      res(res: Response) {
        return { statusCode: res.statusCode };
      },
    },
  }),
);

// ALLOWED_ORIGIN env var: comma-separated list of origins, or "*" to allow all.
// Defaults to allowing any origin so it works both on Replit and cross-domain (Vercel → Render).
const rawOrigin = process.env["ALLOWED_ORIGIN"];
const corsOrigin: cors.CorsOptions["origin"] = rawOrigin
  ? rawOrigin === "*"
    ? true
    : rawOrigin.split(",").map((o) => o.trim())
  : true;

app.use(cors({ origin: corsOrigin, credentials: true }));

app.use(cookieParser());
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

app.use("/api", router);

export default app;
